import csv
import json
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
INPUT_PATH = BASE_DIR / "data.csv"
OUTPUT_PATH = BASE_DIR / "summary.json"


def read_values(path):
    values = []
    with path.open(newline="", encoding="utf-8") as handle:
        for row in csv.reader(handle):
            if not row:
                continue
            raw = row[0].strip()
            if not raw:
                continue
            try:
                values.append(float(raw))
            except ValueError:
                continue
    return values


def summarize(values):
    if not values:
        return {"rows": 0, "average": 0}
    average = sum(values) / len(values)
    if average.is_integer():
        average = int(average)
    return {"rows": len(values), "average": average}


def main():
    summary = summarize(read_values(INPUT_PATH))
    OUTPUT_PATH.write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")
    return summary


if __name__ == "__main__":
    print(json.dumps(main()))

import csv
import json
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
INPUT_PATH = BASE_DIR / "data.csv"
OUTPUT_PATH = BASE_DIR / "summary.json"


def read_values(path):
    values = []
    with path.open(newline="", encoding="utf-8") as handle:
        for row in csv.reader(handle):
            if not row:
                continue
            raw = row[0].strip()
            if not raw:
                continue
            try:
                values.append(float(raw))
            except ValueError:
                continue
    return values


def summarize(values):
    if not values:
        return {"rows": 0, "average": 0}
    average = sum(values) / len(values)
    if average.is_integer():
        average = int(average)
    return {"rows": len(values), "average": average}


def main():
    summary = summarize(read_values(INPUT_PATH))
    OUTPUT_PATH.write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")
    return summary


if __name__ == "__main__":
    print(json.dumps(main()))

